import heapq


class Scheduler:
    def __init__(self, workers: int = 1):
        self.workers = workers
        self._jobs: list[tuple[str, int]] = []
        self._ids: set[str] = set()

    def submit(self, job_id: str, duration: int) -> None:
        if job_id in self._ids:
            raise ValueError(f"duplicate job id {job_id!r}")
        self._ids.add(job_id)
        self._jobs.append((job_id, duration))

    def run(self) -> list[tuple[str, int, int]]:
        free = [(0, w) for w in range(self.workers)]  # (free_at, worker)
        out = []
        for job_id, duration in self._jobs:
            start, worker = heapq.heappop(free)
            out.append((job_id, start, start + duration))
            heapq.heappush(free, (start + duration, worker))
        return sorted(out, key=lambda r: (r[1], r[0]))

