import heapq
from collections import defaultdict


class Scheduler:
    def __init__(self, workers: int = 1, base_backoff: int = 1):
        self.workers = workers
        self.base_backoff = base_backoff
        self._order: list[str] = []
        self._jobs: dict[str, dict] = {}
        self._report: dict[str, dict] | None = None

    def submit(self, job_id: str, duration: int, depends_on=(), fail_attempts: int = 0,
               max_retries: int = 0) -> None:
        if job_id in self._jobs:
            raise ValueError(f"duplicate job id {job_id!r}")
        self._jobs[job_id] = {
            "duration": duration,
            "deps": tuple(depends_on),
            "fail_attempts": fail_attempts,
            "max_retries": max_retries,
            "seq": len(self._order),
        }
        self._order.append(job_id)

    def _validate(self) -> dict[str, list[str]]:
        dependents: dict[str, list[str]] = defaultdict(list)
        indegree = {j: 0 for j in self._jobs}
        for job_id, job in self._jobs.items():
            for dep in set(job["deps"]):
                if dep not in self._jobs:
                    raise ValueError(f"{job_id!r} depends on unknown job {dep!r}")
                dependents[dep].append(job_id)
                indegree[job_id] += 1
        frontier = [j for j, d in indegree.items() if d == 0]
        visited = 0
        while frontier:
            job = frontier.pop()
            visited += 1
            for nxt in dependents[job]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    frontier.append(nxt)
        if visited != len(self._jobs):
            raise ValueError("dependency cycle detected")
        return dependents

    def _key(self, job_id: str):
        job = self._jobs[job_id]
        return (job["seq"],)

    def run(self) -> list[tuple[str, int, int]]:
        dependents = self._validate()
        report = {j: {"status": "pending", "attempts": 0} for j in self._order}
        waiting = {j: set(job["deps"]) for j, job in self._jobs.items()}
        ready = [self._key(j) for j in self._order if not waiting[j]]
        heapq.heapify(ready)
        backoff: list[tuple[int, tuple]] = []  # (ready_at, key) for retries
        idle = list(range(self.workers))
        running: list[tuple[int, int, str]] = []  # (end, worker, job_id)
        time = 0
        out = []

        def skip_downstream(job_id: str) -> None:
            stack = list(dependents[job_id])
            while stack:
                nxt = stack.pop()
                if report[nxt]["status"] == "pending":
                    report[nxt]["status"] = "skipped"
                    stack.extend(dependents[nxt])

        while ready or running or backoff:
            while backoff and backoff[0][0] <= time:
                heapq.heappush(ready, heapq.heappop(backoff)[1])
            while ready and idle:
                job_id = self._order[heapq.heappop(ready)[-1]]
                worker = heapq.heappop(idle)
                report[job_id]["attempts"] += 1
                end = time + self._jobs[job_id]["duration"]
                heapq.heappush(running, (end, worker, job_id))
            candidates = [t for t in (running[0][0] if running else None, backoff[0][0] if backoff else None) if t is not None]
            time = min(candidates)
            while running and running[0][0] == time:
                end, worker, job_id = heapq.heappop(running)
                heapq.heappush(idle, worker)
                job = self._jobs[job_id]
                attempt = report[job_id]["attempts"]
                if attempt > job["fail_attempts"]:
                    report[job_id]["status"] = "succeeded"
                    out.append((job_id, end - job["duration"], end))
                    for nxt in dependents[job_id]:
                        waiting[nxt].discard(job_id)
                        if not waiting[nxt]:
                            heapq.heappush(ready, self._key(nxt))
                elif attempt <= job["max_retries"]:
                    delay = self.base_backoff * 2 ** (attempt - 1)
                    heapq.heappush(backoff, (time + delay, self._key(job_id)))
                else:
                    report[job_id]["status"] = "failed"
                    skip_downstream(job_id)
        self._report = report
        return sorted(out, key=lambda r: (r[1], r[0]))

    def report(self) -> dict[str, dict]:
        if self._report is None:
            raise RuntimeError("call run() first")
        return {j: dict(r) for j, r in self._report.items()}

